const __pageData = JSON.parse('{"title":"API 请求签名与防重放：HMAC、规范化与 Nonce 状态机","description":"","frontmatter":{"title":"API 请求签名与防重放：HMAC、规范化与 Nonce 状态机","date":"2026-08-05T00:00:00.000Z","category":"后端开发","cover":"/covers/backend.svg","tags":["api-security","hmac","replay-protection","java","redis"],"excerpt":"从签名原文规范化、正文摘要和 HMAC-SHA256 出发，设计带时间窗、Nonce 原子去重与密钥轮换能力的 API 防重放链路。"},"headers":[],"relativePath":"posts/api-hmac-signature-replay-protection.md","filePath":"posts/api-hmac-signature-replay-protection.md","lastUpdated":1785892260000}');
